    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Aberrant-(Sanguin).html&quot; title=&quot;Lignage Aberrant&quot;&gt;Aberrant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Abyssal-(Sanguin).html&quot; title=&quot;Lignage Abyssal&quot;&gt;Abyssal&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-C&#233;leste-(Sanguin).html&quot; title=&quot;Lignage C&#233;leste&quot;&gt;C&#233;leste&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Draconique-(Sanguin).html&quot; title=&quot;Lignage Draconique&quot;&gt;Draconique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-&#201;l&#233;mentaire-(Sanguin).html&quot; title=&quot;Lignage &#201;l&#233;mentaire&quot;&gt;&#201;l&#233;mentaire&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
&lt;/td&gt;&lt;td width=&quot;33%&quot;&gt;
  &lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-F&#233;&#233;rique-(Sanguin).html&quot; title=&quot;Lignage F&#233;&#233;rique&quot;&gt;F&#233;&#233;rique&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Infernal-(Sanguin).html&quot; title=&quot;Lignage Infernal&quot;&gt;Infernal&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Kyton.html&quot; title=&quot;Lignage Kyton&quot;&gt;Kyton&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Mort-Vivant-(Sanguin).html&quot; title=&quot;Lignage Mort-vivant&quot;&gt;Mort-vivant&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Profane-(Sanguin).html&quot; title=&quot;Lignage Profane&quot;&gt;Profane&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
&lt;/td&gt;
&lt;td width=&quot;33%&quot;&gt;
  &lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Sang-Noir-(Sanguin).html&quot; title=&quot;Lignage Sang noir&quot;&gt;Sang noir&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Vou&#233;-&#192;-Un-Grand-Destin-(Sanguin).html&quot; title=&quot;Lignage Vou&#233; &#224; un grand destin&quot;&gt;Vou&#233; &#224; un grand destin&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
  &lt;ul&gt;
    &lt;li&gt;La classe de &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;Sanguin&lt;/a&gt;&lt;/li&gt;
  &lt;/ul&gt;
